from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class VolumeConfirmedMove(Strategy):
    rationale = (
        "Volume-confirmed directional moves indicate a strong market commitment to the direction "
        "of a stock. By identifying such moves and ensuring they are supported by significant volume, "
        "we can take advantage of the momentum generated by large traders or institutions."
    )

    def __init__(self, window: int = 20, move_threshold: float = 0.1, vol_ratio_threshold: float = 1.5) -> None:
        self._window = window
        self._move_threshold = move_threshold
        self._vol_ratio_threshold = vol_ratio_threshold

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.height < self._window:
            return Signal(information_available_at=stamp, weights={})

        moves: dict[str, float] = {}
        for symbol in view.symbols:
            if symbol not in history.columns:
                continue
            df = history.select(
                pl.col("symbol"),
                (pl.col("adj_close") - pl.col("adj_close").shift(1)).alias("move"),
                (pl.col("volume") / pl.col("volume").mean()).alias("vol_ratio"),
            )
            if df.height < self._window:
                continue
            df = df.sort("session_date", descending=True)
            move = float(df.select(pl.sum("move")).item())
            vol_ratio = float(df.filter(pl.col("symbol") == symbol).select(pl.mean("vol_ratio")).item())
            if abs(move) > self._move_threshold and vol_ratio > self._vol_ratio_threshold:
                moves[symbol] = move

        signals: list[str] = [s for s, m in moves.items() if m > 0]
        if not signals:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(signals)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in signals},
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest